/* 从**单一母版** `assets/yomika-mark.svg` 派生图标源。
 *
 *   node .github/scripts/derive-logo.mjs            # 写盘
 *   node .github/scripts/derive-logo.mjs --check    # 只校验派生文件与母版一致
 *
 * 母版是唯一一份几何。这个脚本不重画任何东西，只做两件确定性的变换：
 *
 *   1. `src-tauri/icons/app-icon.svg` —— 打包母版。母版里的颜色用 `currentColor`
 *      以便内联组件跟随主题；独立的 `<img>`/打包器必须拿到字面量墨色，所以这里把
 *      `currentColor` 解析成母版注释里写的两级墨（字形 INK、圆点 ACCENT）。
 *   2. `src-tauri/icons/android-foreground.svg` —— Android 自适应图标的前景层。
 *      它**没有**盘子（底板色由 `icon-manifest.json` 的 `bg_color` 提供），并且字形
 *      缩到画布的 68%：Android 只显示 108dp 画布中间那 72dp，不缩的话可见范围里会
 *      占掉 ~89%，白框贴住启动器遮罩（用户报的「四周边缘太小、图标占得太满」）。
 *      68% 让可见范围里占 ~63%，留出启动器图标惯常的 ~17% 留白。
 *      `android_fg_scale` 这个 manifest 字段在 tauri-cli 2.11.4 里是惰性的（填 50
 *      也不变），所以缩放只能写在源 SVG 里。
 *
 * 两个派生文件里的坐标因此永远等于母版的坐标（或它的一个统一缩放），diff 里不会出现
 * "看着差不多" 的漂移——契约测试 tests/design-system-contract.test.ts 的
 * 「一份几何，处处派生」那一条会逐条核对它们与母版一致。
 */
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const ROOT = resolve('.');
const MASTER = resolve(ROOT, 'assets/yomika-mark.svg');
const APP_ICON = resolve(ROOT, 'src-tauri/icons/app-icon.svg');
const ANDROID_FG = resolve(ROOT, 'src-tauri/icons/android-foreground.svg');

/* 母版里三个颜色槽，解析成打包世界要用的字面量墨色。
 *   YOMIKA_PLATE  → 品牌黑。托盘与任务栏会随系统主题翻面，只读得出暗底的那一版
 *                   在亮色任务栏上就消失了，所以这一档恒定。
 *   YOMIKA_INK    → 亮墨。打包件不是 HTML，拿不到 currentColor。
 *   YOMIKA_ACCENT → 次级墨。圆点在两个世界里都留着自己那一档。
 * 槽名不在这里另抄一份名单：下面从母版里现读（`slotNames`），只有这张表要对得上。 */
const SLOT_VALUES = {
  YOMIKA_PLATE: '#0D0D0D',
  YOMIKA_INK: '#F5F5F5',
  YOMIKA_ACCENT: '#E8E8E8',
};

/* Android 前景层的缩放。68/100 而不是 80：见文件头。 */
const FOREGROUND_SCALE = 0.68;

const master = await readFile(MASTER, 'utf8');

/** 从母版里抠出一段真的几何，而不是在这里重写一遍坐标。 */
function slice(source, startMarker, endMarker, label) {
  const from = source.indexOf(startMarker);
  if (from < 0) throw new Error(`母版里找不到 ${label} 的起点标记 ${startMarker}`);
  const to = endMarker ? source.indexOf(endMarker, from) : source.length;
  if (to < 0) throw new Error(`母版里找不到 ${label} 的终点标记 ${endMarker}`);
  return source.slice(from + startMarker.length, to);
}

/** 母版里的注释是写给"改母版的人"的，派生文件里再抄一遍只会变成两份会漂移的散文。 */
function dropComments(fragment) {
  return fragment.replace(/<!--[\s\S]*?-->/g, '');
}

/** 把母版里的颜色槽名解析成具体的墨色。槽名见母版注释。
 *  名字不叫 `resolve`：那个名字被 `node:path` 的 `resolve` 占了。 */
function resolveSlots(fragment, values) {
  return Object.entries(values).reduce(
    (text, [slot, ink]) => text.replaceAll(slot, ink),
    fragment,
  );
}

/** 母版里真正被当成颜色用的每一个槽名（`fill="YOMIKA_…"`）。名单从母版现读：这里再抄
 *  一份就是第二处会漂移的真相，而 `replaceAll` 遇到不存在的槽名会静默什么都不做——漏一个
 *  槽，派生文件里就会留下一个浏览器认不出的 `fill="YOMIKA_…"`，图标直接画不出来。
 *  只认 `fill=` 里的名字：注释里的 `<!-- YOMIKA_GLYPH -->` 是切片标记，不是颜色。 */
function slotNames(source) {
  const used = [...source.matchAll(/fill="(YOMIKA_[A-Z_]+)"/g)].map((match) => match[1]);
  return [...new Set(used)].sort();
}

const SLOTS = slotNames(master);
for (const slot of SLOTS) {
  if (!(slot in SLOT_VALUES)) {
    throw new Error(`母版用了颜色槽 ${slot}，但 SLOT_VALUES 里没有它的下场；两边必须一起加。`);
  }
}

const PLATE = dropComments(slice(master, '<!-- YOMIKA_PLATE -->', '<!-- YOMIKA_GLYPH -->', '盘子')).trim();
const GLYPH = dropComments(slice(master, '<g id="yomika-glyph">', '</g>', '字形'))
  .replace(/^\s*<g id="yomika-glyph">/, '')
  .replace(/<\/g>\s*$/, '')
  .trim()
  .split('\n')
  .map((line) => line.trim())
  .filter(Boolean)
  .join('\n');

const header = (title, note) => `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512" role="img" aria-labelledby="title desc">
  <title id="title">${title}</title>
  <desc id="desc">${note}</desc>
`;

const appIcon = `${header('Yomika app icon', 'Yomika geometric mark in a rounded square. Derived from assets/yomika-mark.svg; do not edit by hand.')}  <!-- Generated by .github/scripts/derive-logo.mjs from assets/yomika-mark.svg.
       This file holds no geometry of its own: the plate and the glyph below are the
       master's, verbatim. It exists because a packed icon needs the colour slots
       resolved to literals — plate ${SLOT_VALUES.YOMIKA_PLATE}, glyph ${SLOT_VALUES.YOMIKA_INK}, accent dot ${SLOT_VALUES.YOMIKA_ACCENT}.
       The plate stays the literal dark one here (unlike the in-app mark): the
       notification area and the taskbar flip with the system theme, so a mark that
       only reads on a dark bar would disappear on a light one.
       Do not hand-edit: run the script. -->
${resolveSlots(PLATE, SLOT_VALUES).trim()}
  <g id="yomika-glyph">
${resolveSlots(GLYPH, SLOT_VALUES)
  .split('\n')
  .map((line) => `    ${line}`)
  .join('\n')}
  </g>
</svg>
`;

const androidForeground = `${header('Yomika mark', `Yomika mark for Android's adaptive icon, drawn on ${FOREGROUND_SCALE * 100}% of the 512 canvas. Derived from assets/yomika-mark.svg; do not edit by hand.`)}  <!-- Generated by .github/scripts/derive-logo.mjs from assets/yomika-mark.svg.
       No plate: the launcher mask supplies the background and icon-manifest.json
       passes bg_color for it. The mark is drawn on ${FOREGROUND_SCALE * 100}% of the canvas because
       Android shows only the middle 72dp of the 108dp adaptive canvas — at 100%
       the mark lands at ~89% of the visible range and the launcher mask bites it
       (user report: "四周边缘太小、图标占得太满"). ${FOREGROUND_SCALE * 100}% puts it at ~63% of the
       visible range, leaving the ~17% gutter launcher icons normally have.
       The android_fg_scale manifest field is inert in tauri-cli 2.11.4 (50 and 80
       produce byte-identical output), so the scale has to live in the source.
       Do not hand-edit: run the script. -->
  <g transform="translate(256 256) scale(${FOREGROUND_SCALE}) translate(-256 -256)">
${resolveSlots(GLYPH, SLOT_VALUES)
  .split('\n')
  .map((line) => `    ${line}`)
  .join('\n')}
  </g>
</svg>
`;

const check = process.argv.includes('--check');
const targets = [
  [APP_ICON, appIcon, 'src-tauri/icons/app-icon.svg'],
  [ANDROID_FG, androidForeground, 'src-tauri/icons/android-foreground.svg'],
];

let drifted = 0;
for (const [path, content, label] of targets) {
  let existing = null;
  try { existing = await readFile(path, 'utf8'); } catch { /* 还没生成过 */ }
  if (existing === content) {
    console.log(`一致    ${label}（${content.length} 字节）`);
    continue;
  }
  drifted += 1;
  if (check) {
    console.log(`漂移    ${label} 与母版不一致（现 ${existing?.length ?? 0} 字节 / 应为 ${content.length} 字节）`);
    continue;
  }
  await writeFile(path, content, 'utf8');
  console.log(`${existing === null ? '写出' : '更新'}    ${label}（${content.length} 字节）`);
}

if (check && drifted > 0) {
  console.error(`\n${drifted} 个派生文件与母版不一致：跑 node .github/scripts/derive-logo.mjs 重新派生。`);
  process.exit(1);
}
console.log(`\n母版 assets/yomika-mark.svg（${master.length} 字节）是唯一一份几何。`);
